import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class ConstraintSummary {
    private static final int DEFAULT_MAX_MATCHES = 5;

    private final String constraintRef;
    private final double score;
    private final List<ConstraintMatch> matches;

    public ConstraintSummary(
            String constraintRef,
            double score,
            List<ConstraintMatch> matches) {
        this.constraintRef = constraintRef;
        this.score = score;
        this.matches = matches == null
                ? List.of()
                : List.copyOf(matches);
    }

    public String summarize() {
        return summarize(DEFAULT_MAX_MATCHES);
    }

    public String summarize(int maxMatches) {
        if (maxMatches < 0) {
            throw new IllegalArgumentException("maxMatches cannot be negative");
        }

        List<ConstraintMatch> sortedMatches = new ArrayList<>(matches);
        sortedMatches.sort(Comparator.comparingDouble(ConstraintMatch::score));

        StringBuilder summary = new StringBuilder();
        summary.append("Constraint: ")
                .append(constraintRef)
                .append(System.lineSeparator());
        summary.append("Overall score: ")
                .append(score)
                .append(System.lineSeparator());
        summary.append("Matches: ")
                .append(sortedMatches.size())
                .append(System.lineSeparator());

        int displayedMatches = Math.min(maxMatches, sortedMatches.size());

        for (int i = 0; i < displayedMatches; i++) {
            ConstraintMatch match = sortedMatches.get(i);

            summary.append("  ")
                    .append(i + 1)
                    .append(". Score: ")
                    .append(match.score())
                    .append(", Justification: ")
                    .append(match.justification())
                    .append(System.lineSeparator());
        }

        if (sortedMatches.size() > maxMatches) {
            summary.append("  ...")
                    .append(System.lineSeparator());
        }

        return summary.toString();
    }

    public record ConstraintMatch(double score, String justification) {
    }
}

