	List<Paragraph> paragraphs = this.paragraphTextExtractor.getParagraphs(this.config);

	if (CollectionUtils.isEmpty(paragraphs)) {
		return documents;
	}

	for (int i = 0; i < paragraphs.size(); i++) {
		Paragraph paragraph = paragraphs.get(i);
		Paragraph nextParagraph = (i + 1 < paragraphs.size()) ? paragraphs.get(i + 1) : paragraph;

		int startPage = paragraph.getPageNumber();
		int endPage = (i + 1 < paragraphs.size())
				? Math.max(startPage, nextParagraph.getPageNumber() - 1)
				: this.document.getNumberOfPages();

		StringBuilder text = new StringBuilder();

		try {
			for (int pageNumber = startPage; pageNumber <= endPage; pageNumber++) {
				var page = this.document.getPage(pageNumber - 1);
				var mediaBox = page.getMediaBox();

				PDFLayoutTextStripperByArea stripper = new PDFLayoutTextStripperByArea();
				stripper.setSortByPosition(true);
				stripper.addRegion("paragraph",
						new Rectangle((int) mediaBox.getLowerLeftX(), (int) mediaBox.getLowerLeftY(),
								(int) mediaBox.getWidth(), (int) mediaBox.getHeight()));
				stripper.extractRegions(page);

				String pageText = stripper.getTextForRegion("paragraph");
				if (StringUtils.hasText(pageText)) {
					if (text.length() > 0) {
						text.append(System.lineSeparator());
					}
					text.append(pageText);
				}
			}
		}
		catch (Exception ex) {
			throw new IllegalStateException("Unable to extract PDF paragraph text", ex);
		}

		if (!StringUtils.hasText(text)) {
			continue;
		}

		java.util.Map<String, Object> metadata = new java.util.LinkedHashMap<>();
		metadata.put(METADATA_START_PAGE, startPage);
		metadata.put(METADATA_END_PAGE, endPage);
		metadata.put(METADATA_TITLE, paragraph.getTitle());
		metadata.put(METADATA_LEVEL, paragraph.getLevel());

		if (StringUtils.hasText(this.resourceFileName)) {
			metadata.put(METADATA_FILE_NAME, this.resourceFileName);
		}

		documents.add(new Document(text.toString(), metadata));
	}

	return documents;
